            if (!isWeekendPackageDates(request.checkIn(), request.checkOut())) {
                throw new HotelException(ErrorCode.INVALID_REQUEST, "WEEKEND_PACKAGE requires check-in on Friday and check-out on Sunday (exactly 2 nights)");
            }
