    @Test
    void anUnknownReservationIsNotFound() {
        assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
    }

    @Test
    void corporateRequiresAValidCompanyCode() {
        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(new NewReservation(
                        101, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.CORPORATE, null))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(new NewReservation(
                        101, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.CORPORATE, "INVALID"))));
        Reservation corporate = service.create(new NewReservation(
                101, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.CORPORATE, "TECNOSUL"));
        assertEquals(RatePlan.CORPORATE, corporate.ratePlan());
    }

    @Test
    void weekendPackageRequiresFridayToSundayWithExactlyTwoNights() {
        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(new NewReservation(
                        101, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.WEEKEND_PACKAGE, null))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(new NewReservation(
                        101, guest, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 15), 2, RatePlan.WEEKEND_PACKAGE, null))));
        Reservation weekend = service.create(new NewReservation(
                101, guest, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14), 2, RatePlan.WEEKEND_PACKAGE, null));
        assertEquals(RatePlan.WEEKEND_PACKAGE, weekend.ratePlan());
    }

    @Test
    void longStayRequiresAtLeastSevenNights() {
        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(new NewReservation(
                        101, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 16), 2, RatePlan.LONG_STAY, null))));
        Reservation longStay = service.create(new NewReservation(
                101, guest, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 17), 2, RatePlan.LONG_STAY, null));
        assertEquals(RatePlan.LONG_STAY, longStay.ratePlan());
    }

